# End-to-end local fixture for the isolated delta transport/apply path. It creates
# temporary package roots and a temporary target tree; it never changes host settings.
#requires -Version 5.1
$ErrorActionPreference='Stop'
$module=Import-Module (Join-Path $PSScriptRoot '..\src\WindowsServerMigration.psd1') -Force -PassThru
$externalReadinessFixturesPath=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot 'ExternalReadinessEvidenceFixtures.ps1'))
$contractsPath=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\src\DeltaContracts.ps1'))
