    . $WorkflowPath
    . $ExternalReadinessFixturesPath
    function Assert-DeltaWorkflow([bool]$Condition,[string]$Message){if(-not $Condition){throw $Message}}
    # The cancellation fixture writes only a typed request under its temporary
    # state root; no host settings or security privileges are changed.
    if(-not (Get-Command Assert-WsmCancellationBoundary -ErrorAction SilentlyContinue)){function Assert-WsmCancellationBoundary($Token,[string]$Phase){if($Token){throw 'Fixture does not authorize cancellation-token execution.'}}}
    function Get-DeltaWorkflowHash([string]$Path){(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
    function Write-DeltaWorkflowPackage([string]$Root,$Plan,[string]$PlanHash,[long]$Generation,[string]$BaseHash,[bool]$Final,[string]$FreezeHash,$Item){
        [void][IO.Directory]::CreateDirectory($Root);$payload=Join-Path $Root 'payload';[void][IO.Directory]::CreateDirectory($payload)
        # Canonicalize only test-owned source ACLs before capturing the trusted
        # baseline. Some runner temp trees lack the OS auto-inherited control
        # bit until Set-Acl; source and target must both use that persisted form.
        # Exact production ACL comparison remains unchanged.
        foreach($fixtureEntry in (Get-WsmScopeEntries $Item.MigrationSpec $Root)){$fixtureAcl=Get-Acl -LiteralPath $fixtureEntry.SourcePath;Set-Acl -LiteralPath $fixtureEntry.SourcePath -AclObject $fixtureAcl}
        $index=Join-Path $Root 'artifacts.jsonl';$writer=New-Object IO.StreamWriter($index,$false,(New-Object Text.UTF8Encoding($false)));$files=[long]0;$bytes=[long]0;$records=[long]0
        try{
            foreach($entry in (Get-WsmScopeEntries $Item.MigrationSpec $Root)){
                $metadata=Get-WsmFileMetadata $entry.SourcePath $Item.MigrationSpec.Metadata;$data=$null
                if(-not $entry.Directory){$data=Write-WsmPayloadFile $entry.SourcePath $payload 65536;$files++;$bytes+=$data.Bytes}
                $row=[pscustomobject]@{ItemId=$Item.ItemId;RelativePath=$entry.RelativePath;Directory=[bool]$entry.Directory;Metadata=$metadata;Data=$data};$writer.WriteLine(($row | ConvertTo-Json -Compress -Depth 20));$records++
            }
        }finally{$writer.Dispose()}
        $manifest=[pscustomobject][ordered]@{SchemaVersion=1;ToolVersion=$script:ToolVersion;Kind='MigrationPackage';PackageId=[Guid]::NewGuid().ToString();BatchId=$Plan.BatchId;PairId=$Plan.PairId;ApprovalId=$Plan.ApprovalId;PlanHash=$PlanHash;Source=$Plan.Source;Target=$Plan.Target;InventoryRevision=1;DecisionRevision=1;Generation=$Generation;BaseManifestHash=$BaseHash;Final=$Final;FreezeHash=$FreezeHash;ArtifactsHash=(Get-DeltaWorkflowHash $index);Files=$files;Bytes=$bytes;Records=$records;ChunkBytes=65536;Mode='IsolatedPilot'}
