        [pscustomobject]@{Root=$Root;ManifestPath=$manifestPath;Manifest=$manifest;ManifestHash=(Get-DeltaWorkflowHash $manifestPath);IndexPath=$index;Plan=$Plan}
    }
    function New-DeltaWorkflowState($Paths,$Package,$Item,[string]$ActualHash){
        $rows=@([pscustomobject]@{ItemId=$Item.ItemId;Status='Succeeded';CreatedByTool=$true;ActualHash=$ActualHash;Backup='';Target=$Item.MigrationSpec.TargetPath;Error='';NativeCode=0})
        foreach($other in $Package.Plan.Items){if($other.ItemId -cne $Item.ItemId -and $other.Decision -eq 'Include' -and $other.MigrationSpec.Adapter -ne 'FileScope'){$rows+=@([pscustomobject]@{ItemId=$other.ItemId;Status='Succeeded';CreatedByTool=$true;ActualHash='fixture-adapter-hash';Backup='';Target='';Error='';NativeCode=0})}}
        $manualItems=@($Package.Plan.Items | Where-Object {$_.Decision -eq 'Include' -and $_.MigrationSpec.Adapter -eq 'ManualWorkflow'});$evidence=@();foreach($manual in $manualItems){$rows=@($rows | Where-Object ItemId -CNE $manual.ItemId)+@([pscustomobject]@{ItemId=$manual.ItemId;Status='ManualEvidenceRequired';CreatedByTool=$false;ActualHash='';Backup='';Target='';Error='Dedicated product procedure and business evidence required';NativeCode=$null});$evidence+=@([pscustomobject]@{ItemId=$manual.ItemId;Check='ManualRestore';Passed=$true;ManifestHash=$Package.ManifestHash;Generation=1;Owner='fixture manual operator';Evidence='temporary local manual procedure assertion';Utc=[DateTime]::UtcNow.ToString('o');ExpiresUtc=[DateTime]::UtcNow.AddHours(2).ToString('o');ManualEvidence=$true})}
        $stage='Succeeded';if($manualItems.Count){$stage='ManualEvidenceRequired'};$state=[pscustomobject][ordered]@{SchemaVersion=1;ToolVersion=$script:ToolVersion;Kind='OperationState';BatchId=$Package.Manifest.BatchId;PairId=$Package.Manifest.PairId;TargetFingerprint=$Package.Manifest.Target.Fingerprint;PlanHash=$Package.Manifest.PlanHash;RunId=[Guid]::NewGuid().ToString();ManifestHash=$Package.ManifestHash;Generation=1;Stage=$stage;Sequence=0;ResultSequence=0;JournalHash=('0'*64);JournalSegment=0;Items=$rows;Evidence=$evidence;Cutover=$null;PendingOperations=@()}
