    }
    function Reset-DeltaWorkflowTarget([string]$TargetRoot,$Rows,$BasePackage,$Item){
        $full=[IO.Path]::GetFullPath($TargetRoot);$temp=[IO.Path]::GetFullPath($root);if(-not $full.StartsWith($temp.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Fixture reset target escaped its owned temporary root.'}
        if([IO.Directory]::Exists($full)){Remove-Item -LiteralPath $full -Recurse -Force};[void][IO.Directory]::CreateDirectory($full)
        foreach($row in $Rows){$path=$full;if($row.RelativePath){$path=Join-Path $full $row.RelativePath};if($row.Directory){if(-not [IO.Directory]::Exists($path)){[void][IO.Directory]::CreateDirectory($path)}}else{Restore-WsmPayloadBytes $row $BasePackage.Root $path}}
        foreach($row in @($Rows | Where-Object {-not $_.Directory})){if($row.ItemId -ceq $Item.ItemId){$path=$full;if($row.RelativePath){$path=Join-Path $full $row.RelativePath};Set-WsmFileMetadata $path $row.Metadata @{}}}
        foreach($row in @($Rows | Where-Object Directory | Sort-Object {if($_.RelativePath){$_.RelativePath.Split([char]92).Count}else{0}} -Descending)){if($row.ItemId -ceq $Item.ItemId){$path=$full;if($row.RelativePath){$path=Join-Path $full $row.RelativePath};Set-WsmFileMetadata $path $row.Metadata @{}}}
    }
