        $serviceId='2'*64;$manualId='3'*64;$serviceSupplement=[pscustomobject]@{ServiceType='Win32OwnProcess';ErrorControl='Normal';LoadOrderGroup='';DelayedAutoStart=$false;FailureActions=[pscustomobject]@{ResetPeriodSeconds=0;RebootMessage='';Command='';Actions=@()};FailureActionsOnNonCrashFailures=$false;ServiceSidType='None';RequiredPrivileges=@();Environment=@();Triggers=@()};$serviceSpec=[pscustomobject]@{Adapter='Service';Owner='temporary test fixture';Evidence='temporary test fixture';Desired=[pscustomobject]@{Name='FixtureDeltaSvc';DisplayName='Fixture delta service';BinaryPathName='C:\Fixture\service.exe';Account='LocalSystem';Dependencies=@();Description='fixture';Supplement=$serviceSupplement}};$manualSpec=[pscustomobject]@{Adapter='ManualWorkflow';Owner='temporary test fixture';Evidence='temporary test fixture';Product='Fixture product';Procedure='Fixture staged restore and readback';Artifacts=@();BusinessChecks=@('Fixture business acceptance')}
        $plan=[pscustomobject][ordered]@{SchemaVersion=1;ToolVersion=$script:ToolVersion;Kind='MigrationPlan';BatchId=[Guid]::NewGuid().ToString();PairId=[Guid]::NewGuid().ToString();ApprovalId=[Guid]::NewGuid().ToString();Source=$source;Target=$targetHost;Mode='IsolatedPilot';ToolFingerprint=(Get-WsmToolFingerprint);InventoryRevision=1;DecisionRevision=1;Items=@([pscustomobject]@{ItemId=$itemId;Name='Fixture files';Decision='Include';MigrationSpec=$spec},[pscustomobject]@{ItemId=$serviceId;Name='Fixture service';Decision='Include';MigrationSpec=$serviceSpec})}
